class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        def ok(W):
            g = [[] for _ in range(n)]
            for a, b, w in edges:
                if w <= W:
                    g[b].append(a)
            seen = [False] * n
            seen[0] = True
            st = [0]
            cnt = 1
            while st:
                u = st.pop()
                for v in g[u]:
                    if not seen[v]:
                        seen[v] = True
                        cnt += 1
                        st.append(v)
            return cnt == n
        hi = max(w for _, _, w in edges)
        if not ok(hi):
            return -1
        lo = 1
        while lo < hi:
            mid = (lo + hi) // 2
            if ok(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

