class Solution {
    private boolean ok(int W, int n, int[][] edges) {
        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges)
            if (e[2] <= W) g.get(e[1]).add(e[0]);
        boolean[] seen = new boolean[n];
        Deque<Integer> st = new ArrayDeque<>();
        st.push(0); seen[0] = true;
        int cnt = 1;
        while (!st.isEmpty()) {
            int u = st.pop();
            for (int v : g.get(u))
                if (!seen[v]) { seen[v] = true; cnt++; st.push(v); }
        }
        return cnt == n;
    }
    public int minMaxWeight(int n, int[][] edges, int threshold) {
        int hi = 0;
        for (int[] e : edges) hi = Math.max(hi, e[2]);
        if (!ok(hi, n, edges)) return -1;
        int lo = 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (ok(mid, n, edges)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
}

