class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        par = list(range(n))
        def find(x):
            while par[x] != x:
                par[x] = par[par[x]]
                x = par[x]
            return x
        for a, b, w in sorted(edges, key=lambda e: e[2]):
            ra, rb = find(a), find(b)
            if ra != rb:
                par[ra] = rb
            r0 = find(0)
            if all(find(x) == r0 for x in range(n)):
                return w
        return -1

